 public override void _Ready(){try{
 var e=new BattleEngine(PresentationJson.Load<JsonArray>("res://data/content-packs.json"));var l=PresentationJson.Load<JsonArray>("res://data/grayflag-campaign-levels.json").OfType<JsonObject>().Single(v=>v["id"]!.GetValue<string>()=="c01-07");var s=e.CreateState(l);var digest=EcmaJson.Stringify(s);var assets=AssetCatalog.Load();var sc=AuthoredScene.Load("res://data/scenes/c01-07-selected-assembly.json");var r=BoardSceneRendering.Load(sc,l,s["map"]!.AsObject());var b=new BoardView{AnimationsEnabled=false};AddChild(b);b.Configure(new(assets,EnvironmentCatalog.Load(),e.Grids.Get("square4"),e.Catalog,r.Plane),l,sc);BoardGroundView? ground=null;b.ConfigureGround((rules,scene)=>ground=r.Ground(rules,scene));b.ConfigureDynamicState();var empty=s.DeepClone().AsObject();empty["units"]=new JsonArray();b.RenderState(empty);var entries=ground!.DepthEntries.Where(d=>d.Node.Name.ToString().StartsWith("central-landmark-core")&&d.Visual is not null).Select(d=>(d.Visual!,d.Visual!.GlobalBounds)).ToArray();var material=new List<Vector2>();for(int y=365;y<=490;y++)for(int x=733;x<=805;x++){var p=new Vector2(x+.5f,y+.5f);if(entries.Any(v=>v.Item2.HasPoint(p)&&v.Item1.Covers(p)))material.Add(p);}var rows=new JsonArray();var identities=new HashSet<string>();var catalog=new JsonArray();int poses=0;
